-- Yardım merkezi makalelerinin İngilizcesi (20 makale): article_metadata.i18n.en = { title, excerpt, seoTitle, seoDescription, bodyMd, toc }.
--
-- NEDEN: Arayüz dili İngilizce olan kullanıcıya içerik servisi makaleleri İngilizce döndürür (catalog.js artCols; istek dili Accept-Language).
-- Kaynak db-schemas/seed/yds/articles.json ("en" alanı); seed yeni kurulumda bunu yazar, var olan makaleyi yeniden yazmaz → mevcut veritabanları için bu dosya.
-- Şema değişmez, yalnız metadata güncellenir; Türkçe sütunlar aynen kalır. Tekrar koşmak aynı sonucu verir.
-- Önce salt okunur kontrol: SELECT count(*) FROM content.article WHERE article_article_type = 'help';  (20 beklenir)
-- ÇALIŞTIRMA: node scripts/apply-migrations.mjs 2026-11-06-1-help-articles-en.sql
BEGIN;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How do I create my account?", "excerpt": "You can sign up with Apple, Google, or email. On first launch you choose your exam, target score, and exam date; sign-up comes after these steps.", "seoTitle": "How do I create my account? | ODAK Help", "seoDescription": "How to create an ODAK account with Apple, Google, or email: step-by-step sign-up and email verification.", "bodyMd": "You can sign up with Apple, Google, or email. On first launch you choose your exam, target score, and exam date; sign-up comes after these steps.\n\n1. Open the app or the website and tap \"Get started\".\n2. Enter your goal and exam date.\n3. Take the level assessment or skip it for now.\n4. Create an account to save your result and plan.\n5. Read the KVKK (Turkish data protection law) consents and continue.\n\nIf you sign up with email, we send a verification link to your address. If it doesn't arrive, check your spam folder.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-hesap-olusturma' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "I forgot my password. What should I do?", "excerpt": "On the sign-in screen, tap \"Forgot password\" and enter your registered email address. We'll send a reset link to that address.", "seoTitle": "I forgot my password. What should I do? | ODAK Help", "seoDescription": "Forgot your ODAK password? Learn how to request a reset link and what to do if the email doesn't arrive.", "bodyMd": "On the sign-in screen, tap \"Forgot password\" and enter your registered email address. We'll send a reset link to that address.\n\n- The link is valid for a short time; if it has expired, request a new one.\n- If the email doesn't arrive, check your spam folder.\n- If you signed up with Apple or Google, there is no password; sign in with the same method.\n\nYour new password must be at least 8 characters. Don't share your password with anyone. If you think someone accessed your account without permission, change your password and write to us.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-sifre-sifirlama' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How can I download my data?", "excerpt": "You can download your account data as a file. On the Settings page, go to the \"Privacy and data\" section and tap \"Download my data\".", "seoTitle": "How can I download my data? | ODAK Help", "seoDescription": "Learn how to download your ODAK account data from Settings and what the file contains.", "bodyMd": "You can download your account data as a file. On the Settings page, go to the \"Privacy and data\" section and tap \"Download my data\".\n\nThe file contains your profile information, the questions you solved and your answers, your mistake notebook, your vocabulary progress, your notes, and your Tutor chats. It may take a few minutes to prepare; when it's ready, we send a link to your registered email address.\n\nThe link is valid for a limited time. Requesting your data is one of your rights under KVKK (Turkish data protection law) and it is free of charge.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-veri-indirme' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How do I delete my account?", "excerpt": "You can delete your account from the \"Delete account\" section on the Settings page. If you want to download your data first, use \"Download my data\" before you start.", "seoTitle": "How do I delete my account? | ODAK Help", "seoDescription": "Steps to delete your ODAK account, how it affects your subscription, and what happens to your data.", "bodyMd": "You can delete your account from the \"Delete account\" section on the Settings page. If you want to download your data first, use \"Download my data\" before you start.\n\n- If you have an active subscription, we recommend cancelling it first; deleting your account cancels the subscription automatically, but refund terms are evaluated separately.\n- After you request deletion, your account is closed and your personal data is deleted or anonymized, except for legally required retention periods.\n- This action cannot be undone.\n\nInformation that must be kept by law, such as invoice records, is retained until the retention period ends.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-hesap-silme' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How do I change my email address?", "excerpt": "You can change your email address from the \"Account\" section on the Settings page.", "seoTitle": "How do I change my email address? | ODAK Help", "seoDescription": "Learn how to change the email address on your ODAK account and how verification works.", "bodyMd": "You can change your email address from the \"Account\" section on the Settings page.\n\n1. Tap the \"Email address\" row.\n2. Enter your new address.\n3. Click the verification link sent to your new address.\n\nYour old address stays active until verification is complete. If you sign in with Apple or Google, your email is tied to that account's settings; use the relevant account provider to change it. If you run into problems, you can write to us from the help center.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-eposta-degistirme' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "Which payment methods are accepted?", "excerpt": "You can pay with a debit or credit card. Your bank may ask for an SMS confirmation (3D Secure) during payment.", "seoTitle": "Which payment methods are accepted? | ODAK Help", "seoDescription": "ODAK payment methods: card payment, 3D Secure, subscriptions, and how the exam period pass differs in renewal.", "bodyMd": "You can pay with a debit or credit card. Your bank may ask for an SMS confirmation (3D Secure) during payment.\n\n- With subscription plans, your card is charged again each period.\n- The exam period pass is a one-time payment and does not renew automatically.\n- If you buy from the mobile app, the payment may be taken through the app store.\n\nIf your card isn't approved, check for your bank's SMS confirmation or try another card. We don't store your card details; they are processed by the payment infrastructure provider.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-odeme-yontemleri' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How do I cancel my subscription?", "excerpt": "You can cancel your subscription any time from the \"Subscription\" section on the Settings page.", "seoTitle": "How do I cancel my subscription? | ODAK Help", "seoDescription": "How to cancel your ODAK subscription: steps, access until the end of the period, and cancelling during the trial.", "bodyMd": "You can cancel your subscription any time from the \"Subscription\" section on the Settings page.\n\n1. Open the Settings page.\n2. Tap the \"Subscription\" row.\n3. Tap \"Cancel subscription\" and confirm.\n\nAfter you cancel, you keep using Premium features until the end of the period you paid for. You won't be charged for the next period. If you cancel during the free trial, you won't pay anything. If you bought through a mobile store, cancel from that store's subscription settings.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-abonelik-iptal' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "Can I get a refund?", "excerpt": "Refund terms depend on the plan you bought and your legal rights. For distance sales, you can request a refund within a set period under your legal right of withdrawal; the details are in the \"Cancellation and Refund\" text.", "seoTitle": "Can I get a refund? | ODAK Help", "seoDescription": "ODAK refund terms: right of withdrawal, founder membership refunds, and how to submit a refund request.", "bodyMd": "Refund terms depend on the plan you bought and your legal rights. For distance sales, you can request a refund within a set period under your legal right of withdrawal; the details are in the \"Cancellation and Refund\" text.\n\n- If the platform doesn't launch during the founder membership pre-sale, your payment is refunded in full.\n- If the service has already started, the scope of the refund is determined by legal regulations.\n- You can submit your refund request through the help center.\n\nAfter your request is reviewed, the refund goes back to the method you paid with; depending on your bank, it can take a few business days.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-iade' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How do I get my invoice?", "excerpt": "Invoices for your payments are listed in the \"Payment methods and invoices\" section on the Settings page. You can download any invoice from there.", "seoTitle": "How do I get my invoice? | ODAK Help", "seoDescription": "How to find your ODAK invoices: individual and corporate invoice details and delivery by email.", "bodyMd": "Invoices for your payments are listed in the \"Payment methods and invoices\" section on the Settings page. You can download any invoice from there.\n\n- For an individual invoice you need your first and last name; for a corporate invoice you need your company title and tax number.\n- Make sure you enter your invoice details correctly during payment.\n- If you want to change your details later, write to us from the help center.\n\nThe invoice is also sent to your registered email address. If it doesn't arrive, check your spam folder.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-fatura' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "What's included in the free plan?", "excerpt": "The free plan gives you a solid start to try ODAK and begin studying regularly.", "seoTitle": "What's included in the free plan? | ODAK Help", "seoDescription": "What the ODAK free plan includes: daily question, Tutor message, flashcard, and mini mock exam limits.", "bodyMd": "The free plan gives you a solid start to try ODAK and begin studying regularly.\n\n- 15 questions per day\n- 5 Tutor messages per day\n- 20 flashcards\n- 1 mini mock exam per month\n- Level assessment, quick notes, and mistake notebook\n\nLimits reset every day; your mini mock exam allowance resets at the start of the month. Limits may change over time. If you want more questions, messages, and detailed analysis, you can upgrade to Premium; but the free plan can be used indefinitely.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-ucretsiz-plan' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "What's included in Premium?", "excerpt": "Premium expands the limits of the free plan and offers more detailed analysis.", "seoTitle": "What's included in Premium? | ODAK Help", "seoDescription": "What ODAK Premium includes: unlimited questions, Tutor messages, full mock exams, analysis, and the 349 TRY/month price.", "bodyMd": "Premium expands the limits of the free plan and offers more detailed analysis.\n\n- Unlimited question practice\n- 40 Tutor messages per day\n- Full mock exams and detailed analysis\n- Estimated score range\n- All vocabulary decks\n\nThe price is 349 TRY/month, and the first 7 days are free. You can cancel any time. If you'd rather follow the exam schedule, there are also the Exam period pass and yearly plan options.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-premium-neler-var' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "What is the Exam period pass?", "excerpt": "The Exam period pass is a one-time payment that is valid until the next exam session. It costs 1,490 TRY.", "seoTitle": "What is the Exam period pass? | ODAK Help", "seoDescription": "The ODAK Exam period pass: 1,490 TRY one-time payment, valid until the next session, does not renew automatically.", "bodyMd": "The Exam period pass is a one-time payment that is valid until the next exam session. It costs 1,490 TRY.\n\n- It does not renew automatically; it ends on its own when the period is over.\n- It includes all Premium features.\n- After the exam session has passed, you can move to a new pass or go back to the free plan.\n\nIt's a good option if you start studying a set time before the exam. If you'll be studying for a long time, the yearly plan may be more economical.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-sinav-donemi-paketi' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How do I switch between plans?", "excerpt": "You can change your plan from the \"Subscription\" section on the Settings page.", "seoTitle": "How do I switch between plans? | ODAK Help", "seoDescription": "Switching between ODAK plans: monthly, yearly, exam period, and founder membership prices, and how your data is kept.", "bodyMd": "You can change your plan from the \"Subscription\" section on the Settings page.\n\n- If you switch from monthly to yearly, the new period starts on your next payment date.\n- When your Exam period pass ends, you can switch to another plan.\n- The yearly plan is 2,490 TRY and the founder membership price is 1,790 TRY.\n- If you go back to the free plan, your data is not deleted; only the limits apply.\n\nThe time you've already paid for is taken into account when you switch. If you're not sure about something, write to us from the help center.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-plan-gecisi' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "What is the Tutor? Is it a person?", "excerpt": "The Tutor in ODAK is an AI tutor, not a human. It explains your questions, breaks sentences into parts, coaches your translations, and helps you find out why you got things wrong.", "seoTitle": "What is the Tutor? Is it a person? | ODAK Help", "seoDescription": "The ODAK Tutor is an AI-powered tutor. What it does, what it doesn't do, and how it differs from a human teacher.", "bodyMd": "The Tutor in ODAK is an AI tutor, not a human. It explains your questions, breaks sentences into parts, coaches your translations, and helps you find out why you got things wrong.\n\nWe call human instructors \"hoca\"; the Tutor is always AI. When the Tutor isn't sure, it says so and tries to show its source. When making exam decisions, you should rely on ÖSYM's official announcements.\n\nThis information is stated clearly in your first chat with the Tutor and on the About page.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-ogretmen-nedir' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "What should I do if the Tutor gives wrong information?", "excerpt": "AI can sometimes make mistakes. If you doubt something the Tutor told you, do the following:", "seoTitle": "What should I do if the Tutor gives wrong information? | ODAK Help", "seoDescription": "What to do if the ODAK Tutor gives wrong information: how to report an error and how to verify information.", "bodyMd": "AI can sometimes make mistakes. If you doubt something the Tutor told you, do the following:\n\n1. Tap the \"Report an issue\" button under the message and briefly write the reason.\n2. Verify important information (dates, scores, application requirements) from ÖSYM's official announcement.\n3. Ask the question again to get a different explanation.\n\nThe errors you report are reviewed by our content team. Thank you for helping with this process. The Tutor tries to say so when it isn't sure; it's a good idea to double-check even when it doesn't.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-ogretmen-yanlis-bilgi' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "What is the daily Tutor message limit?", "excerpt": "The number of messages you can send to the Tutor depends on your plan.", "seoTitle": "What is the daily Tutor message limit? | ODAK Help", "seoDescription": "ODAK Tutor message limits: 5 per day on the free plan, 40 per day on Premium, and when they reset.", "bodyMd": "The number of messages you can send to the Tutor depends on your plan.\n\n- Free plan: 5 messages per day\n- Premium: 40 messages per day\n\nThe limit resets every morning. When you reach your limit, we show it to you clearly; you can use it again tomorrow morning. You can see your remaining allowance at the bottom of the chat screen.\n\nTo use your limit efficiently, combine your questions into one message and include the context (the sentence, the options) together. Limits may change over time.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-mesaj-limiti' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "Are my Tutor chats stored?", "excerpt": "Yes, your chats are stored in your account so you can look back and continue them. In the chat list, you can swipe a chat left to delete or pin it.", "seoTitle": "Are my Tutor chats stored? | ODAK Help", "seoDescription": "How ODAK Tutor chats are stored, how to delete them, and how they are included in data downloads.", "bodyMd": "Yes, your chats are stored in your account so you can look back and continue them. In the chat list, you can swipe a chat left to delete or pin it.\n\n- Deleted chats are removed from your account.\n- When you download all your data, your chats are included in the file.\n- If you delete your account, your chats are also deleted, except for legally required retention periods.\n\nWe recommend not writing highly sensitive personal information (ID number, bank details) in chats. Details of data processing are in the KVKK (Turkish data protection law) privacy notice.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-sohbet-saklama' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "How is the YDS score calculated?", "excerpt": "The YDS has 80 questions and each correct answer is worth 1.25 points. Score = number of correct answers × 1.25.", "seoTitle": "How is the YDS score calculated? | ODAK Help", "seoDescription": "YDS score calculation: correct answers times 1.25. How many correct answers you need for target scores, and about the estimated score.", "bodyMd": "The YDS has 80 questions and each correct answer is worth 1.25 points. Score = number of correct answers × 1.25.\n\nExamples:\n\n- 40 correct = 50 points\n- 44 correct = 55 points\n- 56 correct = 70 points\n- 64 correct = 80 points\n\nThe estimated score in ODAK is shown as a range based on the questions you've solved. This is an estimate; it does not guarantee your actual exam result. Official results are announced by ÖSYM.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-puan-hesabi' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "Does a wrong answer cancel out a correct one?", "excerpt": "No. In the YDS, wrong answers do not cancel out correct answers. Each correct answer is worth 1.25 points; a wrong or blank answer does not reduce your score.", "seoTitle": "Does a wrong answer cancel out a correct one? | ODAK Help", "seoDescription": "In the YDS, a wrong answer doesn't cancel a correct one. Why leaving blanks doesn't help and how to manage your time in the exam.", "bodyMd": "No. In the YDS, wrong answers do not cancel out correct answers. Each correct answer is worth 1.25 points; a wrong or blank answer does not reduce your score.\n\nSo even on questions you're unsure about, it makes sense to eliminate options and mark one. Leaving a blank gains you nothing. For time management, mark the hard questions and move on, then fill in the remaining blanks at the end.\n\nFor the current rules of the exam, you should rely on the guide published by ÖSYM.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-yanlis-dogruyu-goturur-mu' AND a.article_item_revision_id = i.item_published_revision_id;

UPDATE content.article a
   SET article_metadata = jsonb_set(COALESCE(a.article_metadata, '{}'), '{i18n}', COALESCE(a.article_metadata->'i18n', '{}') || jsonb_build_object('en', $en${"title": "Where can I see the exam dates?", "excerpt": "Exam dates are announced by ÖSYM. On the \"Exam calendar\" page in ODAK, you can see the YDS, e-YDS, and YÖKDİL sessions and start a countdown by choosing the date you're aiming for.", "seoTitle": "Where can I see the exam dates? | ODAK Help", "seoDescription": "Where to find YDS, e-YDS, and YÖKDİL exam dates: about the ODAK exam calendar and countdown.", "bodyMd": "Exam dates are announced by ÖSYM. On the \"Exam calendar\" page in ODAK, you can see the YDS, e-YDS, and YÖKDİL sessions and start a countdown by choosing the date you're aiming for.\n\nThe 2026-YDS/2 exam will be held on November 22. Application dates and late application days may change each period; for exact information, check ÖSYM's announcement.\n\nWhen you choose your exam date, your plan is rebuilt around it. You can change the date later from the Settings page.", "toc": []}$en$::jsonb))
  FROM content.item i
 WHERE i.item_external_ref = 'a-help-sinav-tarihleri' AND a.article_item_revision_id = i.item_published_revision_id;

COMMIT;
